import React, { useState, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
  faPhone,
  faEye,
  faEllipsisV,
  faPen,
  faHistory,
  faMoneyBillWave,
  faPrint,
  faTrash,
  faChevronLeft,
  faChevronRight,
  faExclamationTriangle,
  faInbox,
  faRotateRight
} from '@fortawesome/free-solid-svg-icons';
import { formatRupee } from './SupplierKPIs';
import './SupplierTable.css';

const SupplierTable = ({
  data = [],
  loading = false,
  error = null,
  onRetry,
  onViewSupplier,
  onEditSupplier,
  onOpenLedger,
  onDeleteSupplier,
  user,
  searchTerm = ''
}) => {
  const { t } = useTranslation();

  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);

  // Active row dropdown menu tracking
  const [activeMenuCode, setActiveMenuCode] = useState(null);

  const toggleActionMenu = (code, e) => {
    e.stopPropagation();
    setActiveMenuCode(prev => (prev === code ? null : code));
  };

  // Close action menu when clicking outside
  React.useEffect(() => {
    const handleDocumentClick = () => setActiveMenuCode(null);
    document.addEventListener('click', handleDocumentClick);
    return () => document.removeEventListener('click', handleDocumentClick);
  }, []);

  // Pagination calculations
  const totalRecords = data.length;
  const totalPages = Math.max(1, Math.ceil(totalRecords / pageSize));

  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return data.slice(start, start + pageSize);
  }, [data, currentPage, pageSize]);

  // Adjust page if data length shrinks
  React.useEffect(() => {
    if (currentPage > totalPages) {
      setCurrentPage(1);
    }
  }, [totalPages, currentPage]);

  // Print single supplier statement or dispatch
  const handlePrintSupplier = (row) => {
    window.open(`/print-report?period=date&type=purchase&code=${row.code}`, '_blank');
  };

  // 1. Error state
  if (error) {
    return (
      <div className="supplier-table-container">
        <div className="erp-table-error">
          <FontAwesomeIcon icon={faExclamationTriangle} className="text-danger empty-icon" />
          <div className="empty-title text-danger">{error}</div>
          {onRetry && (
            <button className="btn-erp-primary" onClick={onRetry}>
              <FontAwesomeIcon icon={faRotateRight} />
              <span>{t('retry_loading') || 'மீண்டும் முயற்சிக்கவும்'}</span>
            </button>
          )}
        </div>
      </div>
    );
  }

  // 2. Loading state (Skeleton)
  if (loading && data.length === 0) {
    return (
      <div className="supplier-table-container">
        <div className="desktop-table-scroll">
          <table className="erp-table">
            <thead>
              <tr>
                <th style={{ width: '60px' }}>{t('S.No') || 'வ.எண்'}</th>
                <th>{t('col_supplier') || 'சப்ளையர்'}</th>
                <th>{t('col_mobile') || 'மொபைல்'}</th>
                <th>{t('col_city') || 'நகரம்'}</th>
                <th className="text-center">{t('col_commission') || 'கமிஷன் %'}</th>
                <th className="text-right">{t('col_total_purchase') || 'மொத்த கொள்முதல்'}</th>
                <th className="text-right">{t('col_paid') || 'செலுத்தியது'}</th>
                <th className="text-right">{t('col_payable') || 'செலுத்த வேண்டியது'}</th>
                <th>{t('col_last_tx') || 'கடைசி பரிவர்த்தனை'}</th>
                <th className="text-right">{t('col_actions') || 'செயல்கள்'}</th>
              </tr>
            </thead>
            <tbody>
              {[1, 2, 3, 4, 5].map((i) => (
                <tr key={i} className="skeleton-row">
                  <td><div className="skeleton-box" style={{ width: '25px' }} /></td>
                  <td><div className="skeleton-box" style={{ width: '140px' }} /></td>
                  <td><div className="skeleton-box" style={{ width: '100px' }} /></td>
                  <td><div className="skeleton-box" style={{ width: '90px' }} /></td>
                  <td><div className="skeleton-box mx-auto" style={{ width: '50px' }} /></td>
                  <td><div className="skeleton-box ms-auto" style={{ width: '85px' }} /></td>
                  <td><div className="skeleton-box ms-auto" style={{ width: '85px' }} /></td>
                  <td><div className="skeleton-box ms-auto" style={{ width: '90px' }} /></td>
                  <td><div className="skeleton-box" style={{ width: '70px' }} /></td>
                  <td><div className="skeleton-box ms-auto" style={{ width: '70px' }} /></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  }

  // 3. Empty state
  if (data.length === 0) {
    return (
      <div className="supplier-table-container">
        <div className="erp-table-empty">
          <FontAwesomeIcon icon={faInbox} className="empty-icon" />
          <div className="empty-title">
            {searchTerm
              ? (t('no_supplier_search_results') || 'தேடலுக்குரிய சப்ளையர் விவரங்கள் கிடைக்கவில்லை')
              : (t('no_suppliers_found') || 'சப்ளையர்கள் எவரும் பதிவு செய்யப்படவில்லை')}
          </div>
          <div className="empty-desc">
            {searchTerm
              ? 'வேறு பெயரோ குறியீடோ உள்ளிட்டு தேடவும் அல்லது வடிகட்டிகளை மீட்டமைக்கவும்.'
              : '+ புதிய சப்ளையர் பொத்தானைப் பயன்படுத்தி சப்ளையரை சேர்க்கவும்.'}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="supplier-table-container">
      {/* Desktop View: Full ERP Table */}
      <div className="desktop-table-scroll">
        <table className="erp-table">
          <thead>
            <tr>
              <th style={{ width: '60px' }}>{t('S.No') || 'வ.எண்'}</th>
              <th>{t('col_supplier') || 'சப்ளையர்'}</th>
              <th>{t('col_mobile') || 'மொபைல்'}</th>
              <th>{t('col_city') || 'நகரம்'}</th>
              <th className="text-center">{t('col_commission') || 'கமிஷன் %'}</th>
              <th className="text-right">{t('col_total_purchase') || 'மொத்த கொள்முதல்'}</th>
              <th className="text-right">{t('col_paid') || 'செலுத்தியது'}</th>
              <th className="text-right">{t('col_payable') || 'செலுத்த வேண்டியது'}</th>
              <th>{t('col_last_tx') || 'கடைசி பரிவர்த்தனை'}</th>
              <th className="text-right" style={{ width: '130px' }}>
                {t('col_actions') || 'செயல்கள்'}
              </th>
            </tr>
          </thead>
          <tbody>
            {paginatedData.map((row, index) => {
              const serialNo = (currentPage - 1) * pageSize + index + 1;
              // Accounting for flower market supplier:
              // credit_amount = total purchases received
              // debit_amount = payouts made
              // payable = credit_amount - debit_amount
              const totalPurchase = parseFloat(row.credit_amount || 0);
              const totalPaid = parseFloat(row.debit_amount || 0);
              const payable = totalPurchase - totalPaid;
              const hasPayable = payable > 0;
              const isMenuOpen = activeMenuCode === row.code;
              const commissionVal = row.commission ? `${row.commission}%` : '12.5%';

              return (
                <tr key={row.code || index}>
                  {/* S.No */}
                  <td className="text-muted font-numeric">{serialNo}</td>

                  {/* Supplier Name & Code */}
                  <td>
                    <div className="supplier-cell-main">
                      <span className="supplier-name-text">{row.name}</span>
                      <span className="supplier-code-pill font-numeric">{row.code}</span>
                    </div>
                  </td>

                  {/* Mobile Contact */}
                  <td>
                    {row.contact ? (
                      <a href={`tel:${row.contact}`} className="supplier-phone-link font-numeric">
                        <FontAwesomeIcon icon={faPhone} style={{ fontSize: '0.75rem', opacity: 0.7 }} />
                        <span>{row.contact}</span>
                      </a>
                    ) : (
                      <span className="text-muted">-</span>
                    )}
                  </td>

                  {/* Address / City */}
                  <td>
                    <span className="text-secondary small">{row.address || '-'}</span>
                  </td>

                  {/* Commission % */}
                  <td className="text-center">
                    <span className="commission-badge font-numeric">{commissionVal}</span>
                  </td>

                  {/* Total Purchases (Credit) */}
                  <td className="text-right font-numeric fw-semibold" style={{ color: '#1D4ED8' }}>
                    {formatRupee(totalPurchase)}
                  </td>

                  {/* Paid / Payouts (Debit) */}
                  <td className="text-right font-numeric text-muted">
                    {formatRupee(totalPaid)}
                  </td>

                  {/* Payable Outstanding */}
                  <td className="text-right font-numeric">
                    {hasPayable ? (
                      <span className="erp-badge erp-badge-rose font-numeric">
                        {formatRupee(payable)}
                      </span>
                    ) : (
                      <span className="erp-badge erp-badge-green">
                        {t('badge_settled') || 'செலுத்தப்பட்டது'}
                      </span>
                    )}
                  </td>

                  {/* Last Transaction */}
                  <td>
                    <span className="small text-muted font-numeric">
                      {row.last_transaction_date ? row.last_transaction_date.split('T')[0] : '-'}
                    </span>
                  </td>

                  {/* Row Actions */}
                  <td className="text-right">
                    <div className="table-actions-cell">
                      {/* Primary Quick View Button */}
                      <button
                        className="btn-action-view"
                        onClick={() => onViewSupplier(row)}
                        title={t('action_view') || 'பார்'}
                      >
                        {t('action_view') || 'பார்'}
                      </button>

                      {/* ⋮ More Menu Button */}
                      <div style={{ position: 'relative' }}>
                        <button
                          className="btn-action-more"
                          onClick={(e) => toggleActionMenu(row.code, e)}
                          title={t('action_more') || 'மேலும்'}
                          aria-label="More actions"
                        >
                          <FontAwesomeIcon icon={faEllipsisV} />
                        </button>

                        {/* Dropdown Menu */}
                        {isMenuOpen && (
                          <div className="action-dropdown-menu">
                            <button
                              className="action-dropdown-item"
                              onClick={() => {
                                onViewSupplier(row);
                                setActiveMenuCode(null);
                              }}
                            >
                              <FontAwesomeIcon icon={faEye} />
                              <span>{t('action_view') || 'பார்'}</span>
                            </button>

                            <button
                              className="action-dropdown-item"
                              onClick={() => {
                                onEditSupplier(row);
                                setActiveMenuCode(null);
                              }}
                            >
                              <FontAwesomeIcon icon={faPen} />
                              <span>{t('edit') || 'திருத்த'}</span>
                            </button>

                            <button
                              className="action-dropdown-item"
                              onClick={() => {
                                onOpenLedger(row.code);
                                setActiveMenuCode(null);
                              }}
                            >
                              <FontAwesomeIcon icon={faHistory} />
                              <span>{t('action_ledger') || 'லெட்ஜர்'}</span>
                            </button>

                            <button
                              className="action-dropdown-item"
                              onClick={() => {
                                window.location.href = `/debit-credit?code=${row.code}`;
                                setActiveMenuCode(null);
                              }}
                            >
                              <FontAwesomeIcon icon={faMoneyBillWave} />
                              <span>{t('quick_make_payment') || 'பணம் செலுத்துதல்'}</span>
                            </button>

                            <button
                              className="action-dropdown-item"
                              onClick={() => {
                                handlePrintSupplier(row);
                                setActiveMenuCode(null);
                              }}
                            >
                              <FontAwesomeIcon icon={faPrint} />
                              <span>{t('action_print') || 'அச்சிடு'}</span>
                            </button>

                            {user?.role === 'admin' && (
                              <button
                                className="action-dropdown-item danger"
                                onClick={() => {
                                  onDeleteSupplier(row.code);
                                  setActiveMenuCode(null);
                                }}
                              >
                                <FontAwesomeIcon icon={faTrash} />
                                <span>{t('action_delete') || 'நீக்கு'}</span>
                              </button>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Mobile View: Genuine Mobile ERP Cards */}
      <div className="mobile-card-list">
        {paginatedData.map((row) => {
          const totalPurchase = parseFloat(row.credit_amount || 0);
          const totalPaid = parseFloat(row.debit_amount || 0);
          const payable = totalPurchase - totalPaid;
          const hasPayable = payable > 0;
          const commissionVal = row.commission ? `${row.commission}%` : '12.5%';

          return (
            <div key={row.code} className="mobile-supplier-card">
              <div className="mobile-card-top">
                <div className="mobile-card-name-group">
                  <span className="mobile-card-name">{row.name}</span>
                  <div className="mobile-card-meta">
                    <span className="erp-badge erp-badge-violet font-numeric">{row.code}</span>
                    <span className="commission-badge font-numeric">{commissionVal}</span>
                    {row.address && <span>{row.address}</span>}
                  </div>
                </div>

                {hasPayable ? (
                  <span className="erp-badge erp-badge-rose font-numeric">
                    {formatRupee(payable)}
                  </span>
                ) : (
                  <span className="erp-badge erp-badge-green">
                    {t('badge_settled') || 'செலுத்தப்பட்டது'}
                  </span>
                )}
              </div>

              {row.contact && (
                <div>
                  <a href={`tel:${row.contact}`} className="supplier-phone-link font-numeric">
                    <FontAwesomeIcon icon={faPhone} />
                    <span>{row.contact}</span>
                  </a>
                </div>
              )}

              {/* Financial Summary Box */}
              <div className="mobile-card-financials">
                <div className="fin-item">
                  <span className="fin-label">{t('col_total_purchase') || 'மொத்த கொள்முதல்'}</span>
                  <span className="fin-value font-numeric text-primary">{formatRupee(totalPurchase)}</span>
                </div>
                <div className="fin-item">
                  <span className="fin-label">{t('col_paid') || 'செலுத்தியது'}</span>
                  <span className="fin-value font-numeric text-success">{formatRupee(totalPaid)}</span>
                </div>
              </div>

              {/* Mobile Quick Action Buttons */}
              <div className="mobile-card-actions">
                <button
                  className="btn-erp-secondary w-50"
                  onClick={() => onViewSupplier(row)}
                >
                  <FontAwesomeIcon icon={faEye} />
                  <span>{t('action_view') || 'பார்'}</span>
                </button>
                <button
                  className="btn-erp-primary w-50"
                  onClick={() => {
                    window.location.href = `/debit-credit?code=${row.code}`;
                  }}
                >
                  <FontAwesomeIcon icon={faMoneyBillWave} />
                  <span>{t('quick_make_payment') || 'பணம் செலுத்து'}</span>
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* Table Pagination Footer */}
      <div className="table-pagination-footer">
        <div className="d-flex align-items-center gap-2">
          <span>
            {t('records_count') || 'மொத்த பதிவுகள்'}: <strong className="font-numeric">{totalRecords}</strong>
          </span>
          <span className="text-muted">|</span>
          <div className="d-flex align-items-center gap-1">
            <span className="small">{t('items_per_page') || 'பக்கத்திற்கு'}:</span>
            <select
              className="filter-select py-1 px-2"
              style={{ minWidth: '70px', fontSize: '0.75rem' }}
              value={pageSize}
              onChange={(e) => {
                setPageSize(Number(e.target.value));
                setCurrentPage(1);
              }}
            >
              <option value={10}>10</option>
              <option value={25}>25</option>
              <option value={50}>50</option>
            </select>
          </div>
        </div>

        {/* Pagination Page Controls */}
        <div className="pagination-controls">
          <button
            className="pagination-btn"
            onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
            disabled={currentPage === 1}
            aria-label="Previous page"
          >
            <FontAwesomeIcon icon={faChevronLeft} />
          </button>

          <span className="px-2 font-numeric small">
            {currentPage} / {totalPages}
          </span>

          <button
            className="pagination-btn"
            onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages}
            aria-label="Next page"
          >
            <FontAwesomeIcon icon={faChevronRight} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default SupplierTable;
